sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.mycases-page {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px 40px;
  color: #14213d;
}

.mycases-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.mycases-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #14213d;
}

.mycases-header p {
  margin: 0;
  color: #718096;
  font-size: 13px;
}

.back-link {
  color: #0066cc;
  text-decoration: none;
  font-size: 13px;
  margin-top: 8px;
}

.back-link:hover {
  text-decoration: underline;
}

.mycases-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0,0,0,.06);
}

.table-header {
  padding: 18px 20px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
  color: #14213d;
}

.table-responsive {
  overflow-x: auto;
}

.mycases-table {
  width: 100%;
  border-collapse: collapse;
}

.mycases-table th {
  text-align: left;
  padding: 14px 16px;
  background: #f8fafc;
  color: #475569;
  font-size: 12px;
  font-weight: 700;
  border-bottom: 1px solid #e2e8f0;
}

.mycases-table td {
  padding: 15px 16px;
  border-bottom: 1px solid #edf2f7;
  font-size: 13px;
  color: #334155;
  vertical-align: middle;
}

.mycases-table tbody tr:hover {
  background: #f8fbff;
}

.case-link {
  color: #0569d7;
  font-weight: 700;
  text-decoration: none;
}

.case-link:hover {
  text-decoration: underline;
}

.description-cell {
  max-width: 360px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.status-pill {
  display: inline-block;
  padding: 6px 11px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
}

.status-open {
  background: #f1f5f9;
  color: #475569;
}

.status-progress {
  background: #dbeafe;
  color: #1d4ed8;
}

.status-awaiting {
  background: #fff7ed;
  color: #c2410c;
}

.status-resolved,
.status-closed {
  background: #dcfce7;
  color: #15803d;
}

.empty-state {
  text-align: center;
  padding: 55px 20px;
}

.empty-icon {
  font-size: 38px;
  margin-bottom: 10px;
}

.empty-state h3 {
  margin: 0 0 7px;
  color: #14213d;
}

.empty-state p {
  margin: 0;
  color: #718096;
}

@media (max-width: 700px) {

  .mycases-header {
    flex-direction: column;
    gap: 12px;
  }

}

sp_widget.script:
(function() {

    data.cases = [];

    var currentUserId =
        gs.getUserID();


    var gr =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );


    // Only logged-in employee's cases
    gr.addQuery(
        'request_by',
        currentUserId
    );


    gr.orderByDesc(
        'sys_created_on'
    );

    gr.query();


    while (gr.next()) {

        var statusValue =
            gr.getValue('status');

        var statusLabel =
            gr.getDisplayValue('status');


        // Friendly label fallback
        if (
            statusValue ==
            'awaiting_employee_confirmation'
        ) {

            statusLabel =
                'Awaiting Employee Confirmation';
        }


        var created =
            gr.getDisplayValue(
                'created_on'
            );

        if (!created) {

            created =
                gr.getDisplayValue(
                    'sys_created_on'
                );
        }


        data.cases.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getDisplayValue(
                    'number'
                ),

            category:
                gr.getDisplayValue(
                    'category'
                ),

            status:
                statusLabel,

            status_value:
                statusValue,

            description:
                gr.getDisplayValue(
                    'description'
                ),

            created:
                created

        });

    }

})();
